issue.body:
Here’s a **JSON Schema (Draft 2020-12)** that validates both the nested agent profile JSON and the normalized flat row. It enforces the canonical enums so outputs from different agents stay comparable. Agent-friendly interfaces tend to converge on the same attributes — machine-readable specs, standard auth, structured errors, pagination, idempotency, versioning — which makes strict schemas practical here. [^1][^2]

## 1) Schema for the flat/normalized row

```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.com/schemas/agent-integration-profile.flat.json",
  "title": "AgentIntegrationProfileFlat",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "agent_id",
    "runtime",
    "deployment_type",
    "preferred_interface",
    "auth_preferred",
    "request_format",
    "response_format",
    "error_format"
  ],
  "properties": {
    "agent_id": { "type": "string", "minLength": 1 },
    "agent_vendor": { "type": ["string", "null"] },
    "agent_version": { "type": ["string", "null"] },

    "runtime": {
      "type": "string",
      "enum": ["chat", "tool-using", "reasoning", "multi-agent", "embedded"]
    },
    "model_family": { "type": ["string", "null"] },
    "deployment_type": {
      "type": "string",
      "enum": ["hosted-saas", "cloud", "self-hosted", "local", "hybrid"]
    },
    "can_inspect_private_endpoints": { "type": ["boolean", "null"] },

    "preferred_interface": {
      "type": "string",
      "enum": ["mcp", "rest-openapi", "json-rpc", "graphql", "grpc", "custom"]
    },
    "supported_interfaces": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": ["mcp", "rest-openapi", "json-rpc", "graphql", "grpc", "custom"]
      },
      "uniqueItems": true
    },
    "preferred_transport": {
      "type": "string",
      "enum": ["https", "http", "sse", "websocket", "grpc"]
    },
    "supports_streaming": { "type": ["boolean", "null"] },
    "versioning_style": {
      "type": "string",
      "enum": ["url-path-major", "header", "query-param", "semver", "none"]
    },

    "auth_preferred": {
      "type": "string",
      "enum": [
        "bearer-token",
        "api-key-header",
        "oauth2-client-credentials",
        "oauth2-auth-code",
        "mtls",
        "signed-request",
        "none"
      ]
    },
    "auth_acceptable": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "bearer-token",
          "api-key-header",
          "oauth2-client-credentials",
          "oauth2-auth-code",
          "mtls",
          "signed-request",
          "none"
        ]
      },
      "uniqueItems": true
    },
    "auth_requires_human": { "type": ["boolean", "null"] },

    "request_format": {
      "type": "string",
      "enum": ["application/json", "text", "ndjson", "stream", "multipart", "form"]
    },
    "response_format": {
      "type": "string",
      "enum": ["application/json", "text", "ndjson", "stream", "multipart", "form"]
    },
    "strict_typing": { "type": ["boolean", "null"] },
    "machine_readable_spec": { "type": ["boolean", "null"] },
    "preferred_specs": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "openapi-3.0+",
          "openapi-3.1",
          "json-schema",
          "mcp-manifest",
          "graphql-sdl",
          "protobuf",
          "asyncapi"
        ]
      },
      "uniqueItems": true
    },
    "needs_examples": { "type": ["boolean", "null"] },
    "stable_field_names": { "type": ["boolean", "null"] },
    "stable_enums": { "type": ["boolean", "null"] },

    "read_only_pref": { "type": ["boolean", "null"] },
    "write_capable_pref": { "type": ["boolean", "null"] },
    "needs_discovery": { "type": ["boolean", "null"] },
    "needs_pagination": { "type": ["boolean", "null"] },
    "needs_filtering": { "type": ["boolean", "null"] },
    "needs_search": { "type": ["boolean", "null"] },
    "needs_sorting": { "type": ["boolean", "null"] },
    "needs_batch": { "type": ["boolean", "null"] },
    "needs_idempotent_writes": { "type": ["boolean", "null"] },
    "needs_file_upload": { "type": ["boolean", "null"] },
    "needs_file_download": { "type": ["boolean", "null"] },
    "needs_async_jobs": { "type": ["boolean", "null"] },

    "error_format": {
      "type": "string",
      "enum": ["rfc7807-problem+json", "json-custom", "text", "html", "none"]
    },
    "standard_http_codes": { "type": ["boolean", "null"] },
    "structured_errors": { "type": ["boolean", "null"] },
    "validation_error_details": { "type": ["boolean", "null"] },
    "retryable_signals": { "type": ["boolean", "null"] },
    "retryable_codes": {
      "type": "array",
      "items": { "type": "integer", "minimum": 100, "maximum": 599 },
      "uniqueItems": true
    },

    "needs_retries": { "type": ["boolean", "null"] },
    "needs_retry_after": { "type": ["boolean", "null"] },
    "needs_rate_limit_handling": { "type": ["boolean", "null"] },
    "backoff_strategy": {
      "type": "string",
      "enum": ["none", "linear", "exponential", "exponential-with-jitter", "custom"]
    },
    "needs_timeout_guidance": { "type": ["boolean", "null"] },
    "needs_circuit_breaker": { "type": ["boolean", "null"] },

    "latency_pref": { "type": "string", "enum": ["low", "medium", "high"] },
    "throughput_pref": { "type": "string", "enum": ["low", "medium", "high"] },
    "payload_sensitivity": { "type": "string", "enum": ["low", "medium", "high"] },
    "concurrency_sensitivity": { "type": "string", "enum": ["low", "medium", "high"] },
    "rate_limit_pref": { "type": ["string", "null"] },

    "needs_conversation_history": { "type": ["boolean", "null"] },
    "needs_persistent_memory": { "type": ["boolean", "null"] },
    "needs_stateful_sessions": { "type": ["boolean", "null"] },
    "needs_external_context": { "type": ["boolean", "null"] },
    "context_window_behavior": { "type": ["string", "null"] },
    "context_loss_failure_mode": { "type": ["string", "null"] },

    "needs_request_ids": { "type": ["boolean", "null"] },
    "needs_trace_ids": { "type": ["boolean", "null"] },
    "needs_logs": { "type": ["boolean", "null"] },
    "needs_audit_trail": { "type": ["boolean", "null"] },
    "needs_webhooks": { "type": ["boolean", "null"] },

    "needs_openapi": { "type": ["boolean", "null"] },
    "needs_mcp": { "type": ["boolean", "null"] },
    "needs_a2a": { "type": ["boolean", "null"] },
    "needs_acp": { "type": ["boolean", "null"] },
    "needs_human_docs": { "type": ["boolean", "null"] },
    "needs_sdk": { "type": ["boolean", "null"] },
    "needs_postman": { "type": ["boolean", "null"] },

    "backward_compatible": { "type": ["boolean", "null"] },
    "deprecation_policy": { "type": ["string", "null"] },
    "breaking_change_tolerance": {
      "type": "string",
      "enum": ["none", "low", "medium", "high"]
    },
    "version_pinning": { "type": ["string", "null"] },

    "sensitive_data_handling": { "type": ["string", "null"] },
    "pii_concerns": { "type": "array", "items": { "type": "string" } },
    "secret_handling": { "type": "array", "items": { "type": "string" } },
    "sandboxing_needs": { "type": ["string", "null"] },
    "data_retention_concerns": { "type": ["string", "null"] },

    "changes_by_model": { "type": ["boolean", "null"] },
    "changes_by_deployment": { "type": ["boolean", "null"] },
    "changes_by_org_size": { "type": ["boolean", "null"] },
    "changes_by_use_case": { "type": ["boolean", "null"] },

    "must_have": { "type": "array", "items": { "type": "string" } },
    "nice_to_have": { "type": "array", "items": { "type": "string" } },
    "deal_breakers": { "type": "array", "items": { "type": "string" } },

    "access_can_inspect": { "type": "array", "items": { "type": "string" } },
    "access_cannot_inspect": { "type": "array", "items": { "type": "string" } },
    "assumptions": { "type": "array", "items": { "type": "string" } },

    "free_form_notes": { "type": ["string", "null"] },
    "caveats": { "type": "array", "items": { "type": "string" } }
  }
}
```

## 2) Schema for the nested/full JSON profile

```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.com/schemas/agent-integration-profile.nested.json",
  "title": "AgentIntegrationProfileNested",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "agentName",
    "runtime",
    "deploymentType",
    "integrationSummary",
    "endpointPreferences",
    "auth",
    "schemaAndContracts",
    "operations",
    "errorsAndRecovery",
    "resilience",
    "performance",
    "contextAndMemory",
    "observability",
    "documentationNeeds",
    "compatibility",
    "securityAndPrivacy",
    "deploymentSensitivity",
    "idealEndpointChecklist",
    "accessLimitations"
  ],
  "$defs": {
    "nullableBool": { "type": ["boolean", "null"] },
    "nullableString": { "type": ["string", "null"] },
    "stringArray": { "type": "array", "items": { "type": "string" } },
    "interface": {
      "type": "string",
      "enum": ["mcp", "rest-openapi", "json-rpc", "graphql", "grpc", "custom"]
    },
    "auth": {
      "type": "string",
      "enum": [
        "bearer-token",
        "api-key-header",
        "oauth2-client-credentials",
        "oauth2-auth-code",
        "mtls",
        "signed-request",
        "none"
      ]
    },
    "tier": { "type": "string", "enum": ["low", "medium", "high"] }
  },
  "properties": {
    "agentName": { "type": "string", "minLength": 1 },
    "agentVendorOrProject": { "$ref": "#/$defs/nullableString" },
    "agentVersion": { "$ref": "#/$defs/nullableString" },
    "runtime": {
      "type": "string",
      "enum": ["chat", "tool-using", "reasoning", "multi-agent", "embedded"]
    },
    "modelFamily": { "$ref": "#/$defs/nullableString" },
    "deploymentType": {
      "type": "string",
      "enum": ["hosted-saas", "cloud", "self-hosted", "local", "hybrid"]
    },
    "canInspectPrivateEndpoints": { "$ref": "#/$defs/nullableBool" },
    "accessConstraints": { "$ref": "#/$defs/stringArray" },

    "integrationSummary": {
      "type": "object",
      "additionalProperties": false,
      "required": ["idealEndpointPurpose"],
      "properties": {
        "idealEndpointPurpose": { "type": "string" },
        "primaryUseCases": { "$ref": "#/$defs/stringArray" },
        "primaryFailureModes": { "$ref": "#/$defs/stringArray" },
        "whatYouNeedToOperateAutonomously": { "$ref": "#/$defs/stringArray" }
      }
    },

    "endpointPreferences": {
      "type": "object",
      "additionalProperties": false,
      "required": ["preferredInterfaceType"],
      "properties": {
        "preferredInterfaceType": { "$ref": "#/$defs/interface" },
        "supportedInterfaceTypes": {
          "type": "array",
          "items": { "$ref": "#/$defs/interface" },
          "uniqueItems": true
        },
        "preferredTransport": {
          "type": "string",
          "enum": ["https", "http", "sse", "websocket", "grpc"]
        },
        "supportsStreaming": { "$ref": "#/$defs/nullableBool" },
        "preferredVersioningStyle": {
          "type": "string",
          "enum": ["url-path-major", "header", "query-param", "semver", "none"]
        },
        "preferredBaseUrlShape": { "$ref": "#/$defs/nullableString" }
      }
    },

    "auth": {
      "type": "object",
      "additionalProperties": false,
      "required": ["preferredMethod"],
      "properties": {
        "preferredMethod": { "$ref": "#/$defs/auth" },
        "acceptableMethods": {
          "type": "array",
          "items": { "$ref": "#/$defs/auth" },
          "uniqueItems": true
        },
        "requiresHumanInTheLoopForAuth": { "$ref": "#/$defs/nullableBool" },
        "needsOAuthScopes": { "$ref": "#/$defs/stringArray" },
        "authNotes": { "$ref": "#/$defs/nullableString" }
      }
    },

    "schemaAndContracts": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "preferredRequestFormat": {
          "type": "string",
          "enum": ["application/json", "text", "ndjson", "stream", "multipart", "form"]
        },
        "preferredResponseFormat": {
          "type": "string",
          "enum": ["application/json", "text", "ndjson", "stream", "multipart", "form"]
        },
        "requiresStrictTyping": { "$ref": "#/$defs/nullableBool" },
        "requiresMachineReadableSpec": { "$ref": "#/$defs/nullableBool" },
        "preferredSpecFormats": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "openapi-3.0+",
              "openapi-3.1",
              "json-schema",
              "mcp-manifest",
              "graphql-sdl",
              "protobuf",
              "asyncapi"
            ]
          },
          "uniqueItems": true
        },
        "needsExamples": { "$ref": "#/$defs/nullableBool" },
        "needsStableFieldNames": { "$ref": "#/$defs/nullableBool" },
        "needsStableEnumValues": { "$ref": "#/$defs/nullableBool" }
      }
    },

    "operations": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "readOnlyPreferred": { "$ref": "#/$defs/nullableBool" },
        "writeCapablePreferred": { "$ref": "#/$defs/nullableBool" },
        "needsDiscovery": { "$ref": "#/$defs/nullableBool" },
        "needsPagination": { "$ref": "#/$defs/nullableBool" },
        "needsFiltering": { "$ref": "#/$defs/nullableBool" },
        "needsSearch": { "$ref": "#/$defs/nullableBool" },
        "needsSorting": { "$ref": "#/$defs/nullableBool" },
        "needsBatchOperations": { "$ref": "#/$defs/nullableBool" },
        "needsIdempotentWrites": { "$ref": "#/$defs/nullableBool" },
        "needsFileUpload": { "$ref": "#/$defs/nullableBool" },
        "needsFileDownload": { "$ref": "#/$defs/nullableBool" },
        "needsAsyncJobs": { "$ref": "#/$defs/nullableBool" }
      }
    },

    "errorsAndRecovery": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "preferredErrorFormat": {
          "type": "string",
          "enum": ["rfc7807-problem+json", "json-custom", "text", "html", "none"]
        },
        "expectsStandardHttpStatusCodes": { "$ref": "#/$defs/nullableBool" },
        "needsStructuredErrors": { "$ref": "#/$defs/nullableBool" },
        "needsValidationErrorDetails": { "$ref": "#/$defs/nullableBool" },
        "needsRetryableErrorSignals": { "$ref": "#/$defs/nullableBool" },
        "retryableStatusCodes": {
          "type": "array",
          "items": { "type": "integer", "minimum": 100, "maximum": 599 },
          "uniqueItems": true
        },
        "errorNotes": { "$ref": "#/$defs/nullableString" }
      }
    },

    "resilience": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "needsRetries": { "$ref": "#/$defs/nullableBool" },
        "needsRetryAfterHandling": { "$ref": "#/$defs/nullableBool" },
        "needsRateLimitHandling": { "$ref": "#/$defs/nullableBool" },
        "preferredBackoffStrategy": {
          "type": "string",
          "enum": ["none", "linear", "exponential", "exponential-with-jitter", "custom"]
        },
        "needsTimeoutGuidance": { "$ref": "#/$defs/nullableBool" },
        "needsCircuitBreakerBehavior": { "$ref": "#/$defs/nullableBool" }
      }
    },

    "performance": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "latencyPreference": { "$ref": "#/$defs/tier" },
        "throughputPreference": { "$ref": "#/$defs/tier" },
        "payloadSizeSensitivity": { "$ref": "#/$defs/tier" },
        "concurrencySensitivity": { "$ref": "#/$defs/tier" },
        "rateLimitPreference": { "$ref": "#/$defs/nullableString" }
      }
    },

    "contextAndMemory": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
