        "needsPersistentMemory": { "$ref": "#/$defs/nullableBool" },
        "needsStatefulSessions": { "$ref": "#/$defs/nullableBool" },
        "needsExternalContextInjection": { "$ref": "#/$defs/nullableBool" },
