      }
    },

    "observability": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "needsRequestIds": { "$ref": "#/$defs/nullableBool" },
        "needsTraceIds": { "$ref": "#/$defs/nullableBool" },
        "needsLogs": { "$ref": "#/$defs/nullableBool" },
        "needsAuditTrail": { "$ref": "#/$defs/nullableBool" },
        "needsCallbacksOrWebhooks": { "$ref": "#/$defs/nullableBool" }
      }
    },

    "documentationNeeds": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
